HELP_TOPICS = {'mode_border_plate': {'title': 'Forme de base : Cadre (Border) ou Plaque / Inlay (Plate)', 'short': 'Bascule entre un cadre ouvert (Border) et une plaque pleine en métal ou verre (Plate).', 'detail': '• CADRE (Border) : le centre reste ouvert (transparent) pour encadrer votre photo ou motif.\n• PLAQUE / INLAY (Plate) : le centre est rempli en métal plein, brossé, en verre semi-transparent ou en lit d’inlay coloré (idéal pour logos, badges et plaques nominatives).'}, 'grow_direction': {'title': 'Sens d’expansion (Extérieur, Intérieur, Centré)', 'short': 'Définit si le cadre s’étend vers l’extérieur, l’intérieur ou à cheval sur le bord de sélection.', 'detail': '• Vers l’extérieur (agrandir l’image) : le cadre se construit hors de votre sélection. Si la marge manque, Borderlay agrandit automatiquement la zone de travail GIMP.\n• Vers l’intérieur : le cadre pousse depuis le bord de sélection vers le centre.\n• Les deux (centré) : le cadre chevauche le bord de sélection (50 % extérieur, 50 % intérieur).'}, 'corner_radii': {'title': 'Coins & rayons (rayon extérieur et intérieur)', 'short': 'Règle l’arrondi des coins extérieurs et intérieurs (0 px = onglet vif à 45°).', 'detail': '• Doux / Moyen / Fin (rayon > 0 px) : crée des coins concentriques arrondis comme une plaque emboutie.\n• Onglet 45° (0 / 0 px) : crée un cadre classique à angles droits de 90° avec véritables joints d’onglet à 45°.\n• Dans l’onglet « 2. Géométrie, rayons & 3D », les rayons extérieur et intérieur sont réglables indépendamment en pixels.'}, 'shape_toolbox': {'title': 'Formes de sélection & alignement', 'short': 'Place une forme comme sélection et l’aligne. Aucun cadre n’est rendu.', 'detail': '• Touchez une catégorie en haut. Chaque forme est une vignette avec son identifiant dessous (par ex. leaf.heart), également copiable sous le grand aperçu.\n• Taille, angle et paramètres dessinent aussitôt la forme en couleur sur l’image.\n• Appliquer retire la couleur et pose la sélection. Fermer sans appliquer retire la couleur et rétablit la sélection précédente.\n• Look inclut les formes de base, une vague et un sourire.\n• Atelier et Team ajoutent flammes, engrenages, feuilles, ornements, motifs festifs, arcs, paramètres de vague, clin d’œil et angle préalable.\n• Une sélection rectangulaire sert de cadre : la forme démarre centrée dedans selon ses proportions. Sans sélection, elle démarre au centre de l’image à environ 60 % du petit côté.\n• Aligner cale la forme sur ce cadre ; les flèches la déplacent par pas en pixels, même hors du cadre ; la largeur redimensionne autour du centre. Seule la forme bouge, pas un calque.'}, 'shape_rotation': {'title': 'Pivoter la forme de sélection (Angle & axe de pivot 9 points)', 'short': 'Pivote uniquement la géométrie du cadre autour du pivot choisi — l’image dessous reste intacte !', 'detail': '• Angle de rotation (-180° à +180°) : pivote la géométrie du cadre ou de la plaque sur la zone de travail.\n• Feuille : pointe en haut, tige en bas. Le pivot « bord bas centre » place la tige au centre de la rosace.\n• Axe de pivot : définit le point d’ancrage (Centre, Coin haut-gauche, Coin bas-droit, etc.).\n• Important : votre photo ou calque n’est PAS pivoté et l’éclairage global reste physiquement cohérent !'}, 'repeat_rotation': {'title': 'Rotation répétée (Angle 1 -> Angle 2, pas & fondu)', 'short': 'Génère automatiquement une série pivotée (éventail / kaléidoscope) avec fondu progressif d’opacité.', 'detail': '• Angle de départ 1 & Angle de fin 2 (°) : définit la plage angulaire de répétition (par ex. 0° à 45°).\n• Pas de rotation (°) : définit l’écart angulaire entre deux copies (par ex. tous les 15°).\n• Cycles : répète le cycle. Chaque passage supplémentaire est légèrement décalé et le fondu continue sur toutes les copies.\n• Limite : les interrupteurs Cycles et Jusqu’à l’angle. Un seul s’applique. L’autre régleur revient d’un clic. Jusqu’à l’angle va du départ jusqu’à ±360°.\n• Paliers de fondu (%) : réduit progressivement l’opacité de la première copie (100 %) jusqu’à la dernière !'}, 'inlay_color': {'title': 'Couleur Verre & Inlay (avec pipette & nuancier)', 'short': 'Définit la couleur propre pour « Verre cristal coloré » ainsi que les gorges et plaques d’inlay.', 'detail': 'Où s’applique cette couleur ?\n1. Avec le matériau « Verre cristal coloré », elle teinte tout le corps en verre et la réfraction.\n2. Avec « Cuvette d’inlay colorée » en mode Plaque, elle colore le miroir intérieur.\n3. Dans l’éditeur multi-zones, elle colore chaque zone réglée sur « Couleur Inlay (inlay) ».\n\nAstuce : cliquez sur la grande barre de couleur pour ouvrir la roue chromatique et la pipette, ou sur l’une des 8 pastilles gemmes.'}, 'metal_gradient': {'title': 'Dégradé métal & largeur de transition', 'short': 'Choisit entre la courbe physique d’alliage à 7 points et les dégradés GIMP natifs.', 'detail': '• Courbe matériau interne à 7 points (recommandé) : calcule la courbe physique d’ombre et de lumière de chaque métal.\n• Dégradé GIMP : remplace la table métallique par un dégradé GIMP personnalisé.\n• Réglez la largeur de transition entre pentes et plateaux via « Douceur du biseau (%) ».'}, 'dual_profile_cut': {'title': 'Coupe transversale interactive & largeur de transition', 'short': 'Montre en direct dans la coupe où agissent couleurs de zones, rainures, opacité de plaque et transitions.', 'detail': '• La coupe affiche le profil d’élévation du bord extérieur (gauche) vers la zone intérieure (droite).\n• À droite, elle indique en direct si l’intérieur est ouvert ou rempli par une plaque à l’opacité choisie (%).\n• Les bandes jaunes aux limites de zones indiquent la largeur de transition active (« Douceur du biseau »).\n• Dans l’onglet 5, cliquez directement sur Z1..Zn dans le graphique pour cibler la ligne correspondante !'}, 'light_vector': {'title': 'Vecteur lumineux 2D, type de source (Faisceau vs Cône) & impact', 'short': 'Pilote graphiquement origine -> point d’impact, angle (°), intensité (%) et largeur/diamètre du faisceau.', 'detail': '• Glissez dans le pavé 2D de la source (point jaune) vers la cible (pointe de flèche) :\n  - La direction fixe l’angle d’incidence (0°–360°, défaut 135° = haut-gauche).\n  - La longueur règle l’intensité spéculaire (%).\n• Cône de lumière (Cône) : projecteur à diamètre de cône réglable (%).\n• Faisceau lumineux (Faisceau) : bandeau lumineux linéaire à largeur réglable (%).'}, 'inner_shimmer': {'title': 'Lueur intérieure suivant le contour', 'short': 'Projette un doux reflet métallique du bord intérieur vers la zone centrale de l’image.', 'detail': 'La lueur intérieure épouse le contour le plus interne du cadre et peut suivre la lumière principale, éclairer en haut à gauche, en contre-jour (bas-droite) ou tout autour.'}, 'surface_finish': {'title': 'Finition : Brossé, Grain, Plumes, Fourrure & Écailles', 'short': 'Règle la texture de surface : Miroir, Satin, Brossé, Grain, Plumes, Fourrure et Écailles.', 'detail': '• Miroir / Satin : surface lisse brillante ou satinée douce.\n• Brossé : fines stries directionnelles avec finesse et angle de brossage.\n• Grain : micro-grain uniforme sans stries directionnelles.\n• Plumes, Fourrure et Écailles : motifs organiques réglables en taille, longueur, densité et direction.\n• Direction « Suit la lumière » (-1) : aligne automatiquement la texture sur la lumière ; un angle fixe (0° = droite) la remplace.'}, 'lighting_glow': {'title': 'Effets lumineux, Brillance & Halo (Bloom)', 'short': 'Pilote la lumière auto, la brillance spéculaire, le halo lumineux (Bloom), le contraste des biseaux et la lueur intérieure.', 'detail': '• Lumière auto (dès Community) ou pavé 2D Cône/Faisceau (Atelier).\n• Brillance & Halo (Bloom) : renforcent les reflets métalliques avec une aura douce.\n• Contraste et douceur de biseau : modulent la transition ombre/lumière.\n• Lueur intérieure : halo épousant le bord interne vers l’image.'}, 'support': {'title': 'Support', 'short': 'Le support est fourni uniquement pour Look, Atelier et Team.', 'detail': 'Le support est fourni uniquement pour Look, Atelier et Team.\nContact : https://www.ready-4-it.com/contact'}}
